     1→#!/usr/bin/env node
     2→
     3→import { google } from 'googleapis';
     4→import { readFileSync, writeFileSync, existsSync } from 'fs';
     5→import { fileURLToPath } from 'url';
     6→import { dirname, join } from 'path';
     7→
     8→const __filename = fileURLToPath(import.meta.url);
     9→const __dirname = dirname(__filename);
    10→
    11→const TOKEN_PATH = join(__dirname, 'tokens.json');
    12→const CREDENTIALS_PATH = join(__dirname, 'credentials.json');
    13→
    14→/**
    15→ * Load the multi-account token configuration
    16→ * @returns {Object} Token configuration with accounts
    17→ */
    18→export function loadTokenConfig() {
    19→  if (!existsSync(TOKEN_PATH)) {
    20→    throw new Error(`Token file not found. Run: npm run setup`);
    21→  }
    22→
    23→  const content = readFileSync(TOKEN_PATH, 'utf8');
    24→  const data = JSON.parse(content);
    25→
    26→  // Check if it's the old single-account format
    27→  if (data.access_token && !data.accounts) {
    28→    // Old format detected, migrate automatically
    29→    console.error('⚠️  Migrating token.json to multi-account format...');
    30→    const migratedConfig = {
    31→      defaultAccount: 'default',
    32→      accounts: {
    33→        default: data
    34→      }
    35→    };
    36→    saveTokenConfig(migratedConfig);
    37→    return migratedConfig;
    38→  }
    39→
    40→  return data;
    41→}
    42→
    43→/**
    44→ * Save the multi-account token configuration
    45→ * @param {Object} config - Token configuration to save
    46→ */
    47→export function saveTokenConfig(config) {
    48→  writeFileSync(TOKEN_PATH, JSON.stringify(config, null, 2), { mode: 0o600 });
    49→}
    50→
    51→/**
    52→ * Get the default account ID
    53→ * @returns {string} Default account ID
    54→ */
    55→export function getDefaultAccount() {
    56→  const config = loadTokenConfig();
    57→  return config.defaultAccount || Object.keys(config.accounts)[0];
    58→}
    59→
    60→/**
    61→ * Set the default account ID
    62→ * @param {string} accountId - Account ID to set as default
    63→ */
    64→export function setDefaultAccount(accountId) {
    65→  const config = loadTokenConfig();
    66→  if (!config.accounts[accountId]) {
    67→    throw new Error(`Account '${accountId}' not found`);
    68→  }
    69→  config.defaultAccount = accountId;
    70→  saveTokenConfig(config);
    71→}
    72→
    73→/**
    74→ * List all configured accounts
    75→ * @returns {Array} Array of account objects with id, email, and scopes
    76→ */
    77→export function listAccounts() {
    78→  const config = loadTokenConfig();
    79→  return Object.entries(config.accounts).map(([id, data]) => ({
    80→    id,
    81→    email: data.email || 'unknown',
    82→    scope: data.scope || '',
    83→    isDefault: id === config.defaultAccount
    84→  }));
    85→}
    86→
    87→/**
    88→ * Load tokens for a specific account
    89→ * @param {string} accountId - Account ID (defaults to default account)
    90→ * @returns {Object} Token object for the account
    91→ */
    92→export function loadTokens(accountId = null) {
    93→  const config = loadTokenConfig();
    94→  const targetAccount = accountId || config.defaultAccount;
    95→
    96→  if (!config.accounts[targetAccount]) {
    97→    const available = Object.keys(config.accounts).join(', ');
    98→    throw new Error(
    99→      `Account '${targetAccount}' not found. Available accounts: ${available}`
   100→    );
   101→  }
   102→
   103→  return config.accounts[targetAccount];
   104→}
   105→
   106→/**
   107→ * Save tokens for a specific account
   108→ * @param {string} accountId - Account ID
   109→ * @param {Object} tokens - Token object to save
   110→ * @param {string} email - Email address for the account (optional)
   111→ */
   112→export function saveTokens(accountId, tokens, email = null) {
   113→  const config = existsSync(TOKEN_PATH) ? loadTokenConfig() : { accounts: {} };
   114→
   115→  if (!config.accounts) {
   116→    config.accounts = {};
   117→  }
   118→
   119→  // Preserve existing email if not provided
   120→  const existingEmail = config.accounts[accountId]?.email;
   121→
   122→  config.accounts[accountId] = {
   123→    ...tokens,
   124→    ...(email && { email }),
   125→    ...(!email && existingEmail && { email: existingEmail })
   126→  };
   127→
   128→  // Set as default if it's the first account
   129→  if (!config.defaultAccount || Object.keys(config.accounts).length === 1) {
   130→    config.defaultAccount = accountId;
   131→  }
   132→
   133→  saveTokenConfig(config);
   134→}
   135→
   136→/**
   137→ * Remove an account
   138→ * @param {string} accountId - Account ID to remove
   139→ */
   140→export function removeAccount(accountId) {
   141→  const config = loadTokenConfig();
   142→
   143→  if (!config.accounts[accountId]) {
   144→    throw new Error(`Account '${accountId}' not found`);
   145→  }
   146→
   147→  delete config.accounts[accountId];
   148→
   149→  // Update default if we removed it
   150→  if (config.defaultAccount === accountId) {
   151→    const remaining = Object.keys(config.accounts);
   152→    config.defaultAccount = remaining.length > 0 ? remaining[0] : null;
   153→  }
   154→
   155→  saveTokenConfig(config);
   156→}
   157→
   158→/**
   159→ * Check if an account's token needs refresh (within 5 minutes of expiry)
   160→ * @param {Object} tokens - Token object
   161→ * @returns {boolean} True if token needs refresh
   162→ */
   163→function needsRefresh(tokens) {
   164→  if (!tokens.expiry_date) return false;
   165→  const expiryTime = new Date(tokens.expiry_date);
   166→  const now = new Date();
   167→  const fiveMinutes = 5 * 60 * 1000;
   168→  return (expiryTime - now) < fiveMinutes;
   169→}
   170→
   171→/**
   172→ * Refresh access token if needed
   173→ * @param {string} accountId - Account ID (defaults to default account)
   174→ * @returns {Object} Current tokens (refreshed if needed)
   175→ */
   176→export async function refreshTokenIfNeeded(accountId = null) {
   177→  const tokens = loadTokens(accountId);
   178→  const targetAccount = accountId || getDefaultAccount();
