node -e "
import { google } from 'googleapis';
import { readFileSync } from 'fs';

const credentials = JSON.parse(readFileSync('scripts/auth/credentials.json', 'utf8'));
const tokens = JSON.parse(readFileSync('scripts/auth/tokens.json', 'utf8'));
const account = tokens.accounts.default;

const { client_id, client_secret } = credentials.installed;
const oauth2Client = new google.auth.OAuth2(client_id, client_secret);

// Force refresh by setting expired credentials
oauth2Client.setCredentials({
    refresh_token: account.refresh_token,
    access_token: account.access_token,
    expiry_date: 1 // Force expired
});

oauth2Client.refreshAccessToken().then(({ credentials }) => {
    console.log('Refreshed!');
    console.log('New token:', credentials.access_token?.substring(0, 50));
    console.log('New expiry:', credentials.expiry_date);
    console.log('New scope:', credentials.scope);
}).catch(err => {
    console.error('Refresh error:', err.message);
});
" 2>&1

